declare(strict_types=1);require_once dirname(__DIR__,2).'/bootstrap.php';require_post();$u=require_auth();try{$d=request_json();$old=(string)($d['currentPassword']??'');$new=(string)($d['newPassword']??'');if(!password_verify($old,(string)$u['password_hash']))json_response(['message'=>'Mevcut şifre yanlış.'],400);if(text_len($new)<8)json_response(['message'=>'Yeni şifre en az 8 karakter olmalı.'],400);db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),(int)$u['id']]);json_response(['message'=>'Şifre değiştirildi.']);}catch(Throwable $e){json_response(['message'=>'Şifre değiştirilemedi.'],500);}
